input.command:
grep -n "require\|launch\|viewport" explorations/microgpt-walk/check.js | head -8; cat > tmp/shots.js <<'EOF'
const { chromium } = require(process.env.PW || 'playwright');
(async () => {
  const b = await chromium.launch();
  const p = await b.newPage({ viewport: { width: 760, height: 900 } });
  const U = 'http://localhost:8766/fortress/microgpt/';
  const jobs = [
    ['arrays.html', 'The program writes it', 'transpose', 900],
    ['arrays.html', 'is a big operator: an operator', 'matoffset', 700],
    ['backward.html', 'The product in line 65', 'line65', 700],
    ['fortress.html', 'Three places in', 'part9', 900],
    ['fortress.html', 'in capitals. They are', 'part9b', 500],
    ['norm-softmax.html', 'is short for softmax', 'sm', 800],
    ['task.html', "The step's first line makes five vectors", 'line47', 700],
    ['attention.html', 'declares for a rank-3 array', 'kh', 400],
  ];
  for (const [page, text, name, h] of jobs) {
    await p.goto(U + page); await p.waitForTimeout(600);
    const y = await p.evaluate(t => { const e = [...document.querySelectorAll('p')].find(x => x.textContent.includes(t)); if (!e) return -1; return e.getBoundingClientRect().top + window.scrollY; }, text);
    if (y < 0) { console.log('MISSING', name); continue; }
    await p.screenshot({ path: `tmp/walk-shots/chg-${name}.png`, clip: { x: 0, y: Math.max(0, y - 140), width: 760, height: h }, fullPage: true });
    console.log('ok', name);
  }
  await b.close();
})();
EOF
cp tmp/shots.js explorations/microgpt-walk/_shots_tmp.js && node explorations/microgpt-walk/_shots_tmp.js; rm explorations/microgpt-walk/_shots_tmp.js

